// Parse one campaign insight row -> campaign_daily row for yesterday
function actVal(arr, types){ if(!Array.isArray(arr)) return 0; for(const t of types){ const a=arr.find(x=>x.action_type===t); if(a&&a.value!=null) return parseFloat(a.value); } return 0; }
const PURCHASE=['omni_purchase','purchase','offsite_conversion.fb_pixel_purchase','app_custom_event.fb_mobile_purchase'];
const INSTALL=['mobile_app_install','omni_app_install','app_install'];
const d=new Date(Date.now()-86400000);
const yest=`${d.getUTCFullYear()}-${String(d.getUTCMonth()+1).padStart(2,'0')}-${String(d.getUTCDate()).padStart(2,'0')}`;
return $input.all().map(({json:c})=>{
  const spend=parseFloat(c.spend||0);
  const conversions=actVal(c.actions,PURCHASE);
  const revenue=actVal(c.action_values,PURCHASE);
  let roas=0;
  if(Array.isArray(c.purchase_roas)&&c.purchase_roas.length) roas=parseFloat(c.purchase_roas[0].value||0);
  else roas= spend>0 ? revenue/spend : 0;
  return { json: {
    campaign_id:c.campaign_id,
    date:yest,
    spend:Math.round(spend*100)/100,
    revenue:Math.round(revenue*100)/100,
    impressions:parseInt(c.impressions||0),
    reach:parseInt(c.reach||0),
    clicks:parseInt(c.clicks||0),
    link_clicks:parseInt(c.inline_link_clicks||0),
    unique_link_clicks:parseInt(c.unique_inline_link_clicks||0),
    conversions:Math.round(conversions),
    app_installs:Math.round(actVal(c.actions,INSTALL)),
    frequency:Math.round(parseFloat(c.frequency||0)*100)/100,
    purchase_roas:Math.round(roas*10000)/10000
  }};
});
